import numpy as np
def equation(eps, T, params):
    a,b,c,d,f,g,h,j,k,i = params[:10]
    num = a + b/T + (c + d*np.sqrt(T) + f/T)*eps + g*eps**2
    den = 1 + (h + j*np.sqrt(T))*eps + k*eps**2
    return -eps*num/den*np.exp(-i*eps)
